window.K_FICHES=[{"id":"melenchon","slug":"jean-luc-melenchon","date":"03/05/2026","statut":"déclaré","site":"https://melenchon2027.fr","prog_url":"https://melenchon2027.fr","prog":"en cours","past":["➖","✅","✅","➖","✅"],"mandats":[["Mandat parlementaire actuel",[["depuis juin 2022","Aucun. Sans mandat, ni parlementaire ni local",""]]],["Mandats parlementaires passés",[["","Sénateur de l'Essonne de 1986 à 2000",""],["","Député européen (Sud-Ouest) : élu 2009 (8,15 %), réélu 2014 (8,57 %) ; siège cédé à Marie-Pierre Vieu en 2017",""],["","Député de la 4e circonscription des Bouches-du-Rhône, 06/2017 - 06/2022 (59,8 % au second tour) ; président du groupe LFI jusqu'en 2021",""]]],["Au gouvernement",[["","Ministre délégué à l'Enseignement professionnel, gouvernement Jospin, 2000 - 2002, auprès de Jack Lang.",""]]],["Mandats locaux",[["","Conseiller municipal de Massy à partir de 1983",""],["1985 - avril 1992","Conseiller général de l'Essonne, canton de Massy-Ouest",""],["","Aucun mandat local depuis.",""]]]],"parcours":[["Profession",[["","Parcours professionnel et politique",""],["","À l'issue d'études de lettres modernes et de philosophie, il devient enseignant après avoir longtemps hésité entre l'enseignement et le journalisme.",""],["","Une profession qu'il exerce peu, puisqu'il devient adjoint au maire de Massy quelque temps après son adhésion au Parti socialiste en 1977, est élu sénateur en 1986, devient ministre de l'Enseignement professionnel dans le gouvernement « Rouge-Rose-Vert » de Lionel Jospin en mars 2000, puis député européen en 2010, et enfin député des Bouches-du-Rhône en 2017.",""],["","Il est notamment l'auteur de 23 essais politiques.",""],["","Institut La Boétie",""],["","Depuis 2023, Jean-Luc Mélenchon est vice-président, aux côtés de Clémence Guetté, de l'Institut La Boétie. Cet institut est un think tank français, créé le 21 octobre 2019, affilié à La France insoumise.",""]]],["Parti et responsabilités",[["","Fondateur du Parti de gauche (2008) puis de La France insoumise (2016)",""],["","Président du groupe LFI à l'Assemblée nationale jusqu'en 2021, puis Mathilde Panot",""],["","Coprésident de l'Institut La Boétie depuis 2023, avec Clémence Guetté",""]]]],"judiciaire":[["","Jean-Luc Mélenchon et ses anciens assistants parlementaires étaient sous le joug d'une enquête de l'Office européen de lutte antifraude depuis 2017 puis d'une information judiciaire en France depuis 2018 (pas de condamnation)",""],["","J.L Mélenchon a été condamné lundi 9 décembre 2019 à trois mois d'emprisonnement avec sursis et 8000 euros d'amende par le tribunal correctionnel de Bobigny pour \"rébellion, provocation directe à la rébellion et intimidation envers des magistrats et des dépositaires de l'autorité publique\" lors de la perquisition du siège du mouvement en octobre 2018","https://www.lemonde.fr/police-justice/article/2019/12/09/perquisition-houleuse-a-lfi-jean-luc-melenchon-et-ses-proches-fixes-sur-leur-sort-lundi_6022145_1653578.html"],["","J.L Mélenchon a été condamné le mercredi 10 juillet 2019 par le Tribunal de Paris, saisi par un ex-journaliste du Monde, Paulo Paranagua, pour l'insuffisance des mentions légales de son site internet en 2016. Mélenchon a été condamné à verser 1 euro symbolique de dommages et intérêts et 2 000 euros de frais de justice au journaliste.","https://www.ouest-france.fr/politique/jean-luc-melenchon/jean-luc-melenchon-condamne-pour-l-insuffisance-des-mentions-legales-de-son-site-internet-6440667"],["","J.L Mélenchon a été condamné pour diffamation envers un ex-journaliste du journal Le Monde, Paulo Paranagua, le 17 septembre 2021 par le Tribunal correctionnel de Paris pour \"diffamation publique\". Il l'avait qualifié en novembre 2016 \"d'assassin repenti\" dans son blog \"l'ère du peuple\".",""],["","J.L Mélenchon a été condamné mardi 11 janvier 2021 pour \"injures publiques\" et \"diffamation publique\" par le tribunal correctionnel de Paris. Il a été condamné à une amende de 500 euros avec sursis et devra verser 3 000 euros de dommages et intérêts à Radio France. Mélenchon était poursuivi pour des propos tenus dans une vidéo publiée sur son profil Facebook le 19 octobre 2018 où il avait qualifié les journalistes de franceinfo d'\"abrutis\" et de \"menteurs\" après une enquête de la cellule d'investigation de Radio France sur sa campagne présidentielle de 2017. Une vidéo publiée 3 jours après des perquisitions menées au siège de LFI et au domicile de Mélenchon dans le cadre d'une enquête du parquet de Paris sur les comptes de la campagne présidentielle de 2017","http://franceinfo.fr/politique/la-france-insoumise/jean-luc-melenchon-condamne-pour-injure-publique-et-diffamation-envers-radio-france_4912699.html"],["","--> A fait appel",""]],"sources":"• France 24, 03/05/2026 • LCP, maj 06/09/2026 • melenchon2027.fr/construction-programme, 08/09/2026 • Wikipédia, 08/09/2026","pva":true},{"id":"le-pen","slug":"marine-le-pen","date":"08/07/2026","statut":"déclaré","site":"https://marinelepen.com","prog_url":"https://rassemblementnational.fr/livrets-thematiques","prog":"en cours","past":["✅","✅","➖","?","✅"],"mandats":[["Mandat parlementaire actuel",[["","Députée de la 11e circonscription du Pas-de-Calais depuis juin 2017 (réélue 2022 avec 63,21 %, puis dès le premier tour en 2024).",""]]],["Mandats parlementaires passés",[["","Députée européenne : élue 2004 (Île-de-France), réélue 2009 (Nord-Ouest, 10,18 %) et 2014 (33,6 %). Coprésidente du groupe Europe des nations et des libertés à partir de 2015. Démission du PE début juillet 2017, effet rétroactif au 18/06/2017.",""],["","Non-inscrite à l'Assemblée de 2017 à 2022.",""]]],["Au gouvernement",[["","Aucune.",""]]],["Mandats locaux",[["","Conseillère municipale d'Hénin-Beaumont, 2008-2011 ; démissionne pour non-cumul des mandats",""],["","Conseillère régionale Nord-Pas-de-Calais puis des Hauts-de-France, 1998-2004 puis 2010-2021",""],["","Conseillère départementale du canton d'Hénin-Beaumont-2, de 2021 à 2025 (59,7 %)",""],["","Conseillère régionale d'Île-de-France 2004-2010",""]]]],"parcours":[["Profession",[["","Avocate. Inscrite au barreau de Paris en 1992, d'abord au cabinet de Georges-Paul Wagner puis à son compte à partir de 1994. Quitte le barreau en 1998 pour entrer au service juridique du Front national.",""]]],["Parti et responsabilités",[["","Présidente du Front national de janvier 2011 à 2021, élue au congrès de Tours avec 67,65 % des voix des militants. Quitte la tête du parti en 2021 pour se consacrer à sa campagne ; Jordan Bardella en assure l'intérim puis est élu président en novembre 2022",""],["","Présidente du groupe RN à l'Assemblée nationale depuis juin 2022, reconduite le 10/07/2024",""],["","Coprésidente du groupe Europe des nations et des libertés au Parlement européen à partir de 2015",""],["","Directrice du service juridique du FN de 1998 à 2003, vice-présidente du parti à partir de 2003",""]]]],"judiciaire":[["","Affaire des assistants parlementaires européens du FN, détournement de fonds publics.",""],["","31/03/2025, première instance : 4 ans de prison dont 2 ferme, 100 000 € d'amende, 5 ans d'inéligibilité avec exécution provisoire. Le RN : 2 M€ d'amende dont 1 M€ avec sursis.",""],["","07/07/2026, appel : 3 ans dont 2 avec sursis (1 an ferme sous bracelet électronique), 100 000 € d'amende, 45 mois d'inéligibilité dont 30 avec sursis (15 mois ferme).",""],["","Éligibilité 2027 : les 15 mois ferme sont considérés comme purgés depuis mars 2025 (exécution provisoire), ce qui la rend éligible, sous réserve du pourvoi.",""],["08/07/2026","Pourvoi en cassation.",""]],"sources":"Public Sénat, 07/07/2026 • franceinfo, 08/07/2026 • LCP, maj 06/09/2026 • rassemblementnational.fr/livrets-thematiques, 08/09/2026 • Wikipédia, 08/09/2026","pva":true},{"id":"attal","slug":"gabriel-attal","date":"22/05/2026","statut":"déclaré","site":"https://attalpresident.fr","prog_url":"https://attalpresident.fr/programme","prog":"en cours","past":["✅","✅","✅","➖","✅"],"mandats":[["Mandat parlementaire actuel",[["","Député de la 10e circonscription des Hauts-de-Seine depuis 2024",""]]],["Mandats parlementaires passés",[["","Député de la 10e circonscription des Hauts-de-Seine : 2017-2018, 22/06/22-22/07/22, 07/24 à aujourd'hui",""]]],["Au gouvernement",[["16 octobre 2018 - 6 juillet 2020","Secrétaire d'État auprès du ministre de l'Éducation nationale et de la Jeunesse",""],["6 juillet 2020 - 20 mai 2022","Porte-parole du gouvernement et Secrétaire d'État auprès du Premier ministre",""],["20 mai 2022 - 20 juillet 2023","Ministre délégué chargé des Comptes publics",""],["20 juillet 2023 - 11 janvier 2024","Ministre de l'Éducation nationale et de la Jeunesse",""],["","Premier ministre français, 9 janvier - 5 septembre 2024, le plus jeune de la Ve République. Dissolution de juin 2024.",""]]],["Mandats locaux",[["","Conseiller municipal délégué aux Relations institutionnelles et aux Jumelages de Vanves (Hauts-de-Seine)","https://www.vanves.fr/elected/attal-gabriel/"],["","En fonction depuis le 30 mars 2014 sans interruption, il a conservé ce mandat même durant ses fonctions ministérielles et lors de son passage à Matignon.",""],["","En 2014 il était encore membre du Parti socialiste, ensuite réélu à ce poste à l'occasion des scrutins municipaux.",""]]]],"parcours":[["Profession",[["","Gabriel Attal n'a jamais exercé de profession en dehors du secteur politico-administratif.",""],["","Il a suivi une licence de droit à Paris II - Panthéon Assas entre 2008 et 2010 puis un master en affaires publiques à SciencesPo Paris entre 2007 et 2013 (https://www.info.gouv.fr/personnalite/gabriel-attal )",""]]],["Parti et responsabilités",[["","Président du groupe Ensemble pour la République à l'Assemblée nationale depuis juillet 2024",""],["","Secrétaire général de Renaissance. En fonction depuis le 8 décembre 2024",""],["","Porte-parole de La République en marche, 4 janvier - 16 octobre 2018",""]]]],"judiciaire":[["","Que des situations où il est plaignant mais pas de situation où il est mis en cause",""]],"sources":"France 24, 22/05/2026 • LCP • attalpresident.fr/programme, 08/09/2026","pva":true},{"id":"philippe","slug":"edouard-philippe","date":"2024 (mois à préciser)","statut":"déclaré","site":"https://www.edouardphilippe.fr","prog_url":"https://horizonsleparti.fr/les-notes/","prog":"en cours","past":["➖","✅","✅","✅","✅"],"mandats":[["Mandat parlementaire actuel",[["","Aucun. Il est maire du Havre depuis 2020 et ne siège pas au Parlement.",""]]],["Mandats parlementaires passés",[["","Député de la 7ème circonscription de Seine-Maritime 2007-2017 (suppléant de 2007 à 2012) de la 7ème circonscription de Seine-Maritime pour UMP/LR","https://www.assemblee-nationale.fr/13/tribun/fiches_id/345619.asp"]]],["Au gouvernement",[["","Premier ministre, mai 2017 - juillet 2020. Le plus long des gouvernements d'Emmanuel Macron.",""]]],["Mandats locaux",[["","Conseiller municipal du Havre (Seine-Maritime) : 2001-2010 comme Adjoint au Maire",""],["","Conseiller général de Seine-Maritime 2008-2012",""],["","Maire du Havre : 2010-2017, 2020-aujourd'hui",""],["2010 - 2017","Président de la communauté de l'agglomération havraise",""],["2004 - 2008","Conseiller régional de Haute-Normandie",""]]]],"parcours":[["Profession",[["","Diplômé de Sciences Po Paris en 1992 puis de l'École nationale d'administration (ENA) en 1997, il intègre le Conseil d'État et s'occupe de la question du contentieux où il exerce des fonctions jusqu'en 2002.","https://lehavre.fr/ma-ville/le-conseil-municipal/les-elus/edouard-philippe"]]],["Parti et responsabilités",[["","Fondateur et président du parti Horizons depuis octobre 2021",""]]]],"judiciaire":[["","Édouard Philippe n'a pas fait l'objet de condamnation judiciaire, mais objet d'une information judiciaire (cf. l'affaire de la Cité numérique)",""]],"sources":"France 3 Normandie, 03/2026 • ICI • edouardphilippe.fr, 08/09/2026","pva":true},{"id":"retailleau","slug":"bruno-retailleau","date":"19/04/2026","statut":"déclaré","site":"https://www.avecretailleau.fr","prog_url":"https://republicains.fr/nos-propositions/","prog":"en cours","past":["✅","✅","✅","✅","✅"],"mandats":[["Mandat parlementaire actuel",[["","Sénateur de la Vendée (Pays de la Loire) sous l'étiquette Les Républicains",""],["","Élu pour la première fois le 26/09/2004",""],["","Réélu le 28.09.2014",""],["","Réélu le 27.09.2020",""],["","Mandat suspendu du 21.10.2024 au 13.11.2025 pendant qu'il est ministre de l'intérieur",""],["","Redevenu sénateur le 13 novembre 2025",""],["","Il siège à la commission de la Culture, de l'éducation, de la Communication et du sport","https://www.senat.fr/senateur/retailleau_bruno04033b.html"]]],["Mandats parlementaires passés",[["","Député de la 4ème circonscription de la Vendée du 27 novembre 1994 au 21 avril 1997",""],["","Source :","https://www2.assemblee-nationale.fr/sycomore/fiche/6689"],["","- Sénateur de la Vendée (Pays de la Loire) sous l'étiquette Les Républicains",""],["","Élu pour la première fois le 26/09/2004",""],["","Réélu le 28.09.2014",""],["","Réélu le 27.09.2020",""],["","Mandat suspendu du 21.10.2024 au 13.11.2025 pendant qu'il est ministre de l'intérieur",""]]],["Au gouvernement",[["21/09/2024 - 12/10/2025","Ministre de l'Intérieur",""]]],["Mandats locaux",[["","Mandats locaux actuels :",""],["","Membre de la Commission \"Transports, territoires, environnement, énergie\" au sein du groupe \"Aimer et Agir pour les Pays de la Loire\" depuis janvier 2020 selon ses propres déclarations",""],["","Sources : https://www.hatvp.fr/fiche-nominative/?declarant=retailleau-bruno ; https://www.paysdelaloire.fr/mon-conseil-regional/linstitution/les-elus Mandats locaux passés :",""],["","Conseiller général de la Vendée du 3 octobre 1988 au 1er avril 2015",""],["","Président du Conseil général de la Vendée du 30 novembre 2010 au 1er avril 2015",""],["","Vice-Président du Conseil régional des Pays de la Loire du 28 mars 1998 au 2 avril 2004",""],["","Président du Conseil régional des Pays de la Loire du 18 décembre 2015 au 13 septembre 2017",""]]]],"parcours":[["Profession",[["1985","Directeur général adjoint de la radio locale Alouette appartenant à un média fondé par Philippe de Villiers",""],["1987-1994","Directeur général de l'école de communication Sciencescom à Nantes",""],["1989","Premier président du conseil d'administration du Grand Parc du Puy du Fou au côté de Philippe de Villiers",""]]],["Parti et responsabilités",[["","Président des Républicains depuis le 18/05/2025, élu avec 74,3 % des voix face à Laurent Wauquiez",""],["","Président du groupe LR au Sénat d'octobre 2014 à septembre 2024",""]]]],"judiciaire":[["","Aucune condamnation judiciaire à ce jour.",""]],"sources":"• Fiche Komune • LCP, 19/04/2026 • France 24, 18/05/2025 • avecretailleau.fr, 08/09/2026","pva":true},{"id":"david-lisnard","slug":"david-lisnard","date":"31/03/2026","statut":"déclaré","site":"https://www.unenouvelleenergie.fr","prog_url":"https://www.unenouvelleenergie.fr/notre-programme/","prog":"en cours","past":["➖","➖","➖","✅","✅"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire. Il n'a jamais été parlementaire.",""]]],["Mandats parlementaires passés",[["","Aucun. Il a été suppléant de Bernard Brochand pour la XIVe législature (2012-2017) dans la 8e circonscription des Alpes-Maritimes : être suppléant n'est pas un mandat, il n'a pas siégé.",""]]],["Au gouvernement",[["","Aucune. Voir la colonne des fonctions non électives.",""]]],["Mandats locaux",[["","Conseiller municipal de Cannes depuis 2001 : d'abord 2e adjoint de Bernard Brochand (développement économique, tourisme, événementiel, emploi, cultes, proximité), puis premier adjoint à partir de 2008 avec les mêmes délégations",""],["","Maire de Cannes depuis 2014 (58,97 % au second tour), réélu le 15/03/2020 dès le premier tour avec 88,08 %",""],["","Conseiller général des Alpes-Maritimes, élu en 2008 dans le canton de Cannes-Est (52,58 %), réélu en 2015 dès le premier tour dans le nouveau canton de Cannes-2 (54,52 %, avec Chantal Azémar-Morandini) ; conseiller départemental depuis",""],["depuis 2015","Vice-président du conseil départemental des Alpes-Maritimes, délégué au tourisme",""],["","Président de la communauté d'agglomération Cannes Pays de Lérins depuis juillet 2017",""],["","Fonctions non électives à ne pas mélanger : président de la SEMEC (palais des Festivals) depuis 2001, du SICASIL, du comité régional du tourisme Côte d'Azur depuis 2015, de l'Association des maires de France depuis 2021.",""]]]],"parcours":[["Profession",[["","Diplômé de l'IEP de Bordeaux (1992). Propriétaire de magasins de vêtements pour enfants dans les années 1990, dont il revend le dernier en 2016. Président du cabinet de conseil aux collectivités Service Public 2000 à partir de 2008.",""]]],["Parti et responsabilités",[["","Président de Nouvelle Énergie, parti qu'il crée en 2014 et qu'il structure à l'échelle nationale en juin 2021",""],["","Vice-président des Républicains jusqu'en 2026, parti qu'il quitte le 31/03/2026",""],["","Président de l'Association des maires de France depuis novembre 2021, élu avec 62,3 % face à Philippe Laurent",""],["","Président de la SEMEC, gestionnaire du palais des Festivals de Cannes, depuis 2001, et du SICASIL",""],["","Président du comité régional du tourisme Côte d'Azur depuis 2015",""],["","Directeur de cabinet et attaché parlementaire de Jacques Pélissard de 1996 à 1999",""],["","Porte-parole de François Fillon pendant la campagne de 2017",""]]]],"judiciaire":[["","Aucune condamnation pénale documentée.",""],["","Contentieux administratif, à distinguer d'une condamnation personnelle : son arrêté de juillet 2016 sur les tenues de plage. Fin août 2016, le Conseil d'État statue en référé sur l'illégalité d'une telle pratique, à propos de l'arrêté similaire du maire de Villeneuve-Loubet. En 2018, la ville de Cannes est condamnée à rembourser l'amende d'une vacancière verbalisée en vertu de cet arrêté. C'est la commune qui est condamnée, pas lui.",""]],"sources":"• Éléments transmis par la rédaction\n• Wikipédia, « David Lisnard », consulté le 08/09/2026\n• Site de Nouvelle Énergie et unenouvelleenergie.fr/notre-programme","pva":false},{"id":"xavier-bertrand","slug":"xavier-bertrand","date":"27/08/2026","statut":"déclaré","site":"https://www.nousfrance.fr","prog_url":"https://www.nousfrance.fr/#contribuez","prog":"","past":["➖","✅","✅","✅","✅"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire. Il a démissionné de son mandat de député en 2016 après son élection à la présidence de la région.",""]]],["Mandats parlementaires passés",[["","Député de la 2e circonscription de l'Aisne de 2002 à 2016, mais avec trois interruptions : élu le 16/06/2002 (il bat la députée PS sortante Odette Grzegrzulka) ; réélu en 2007 dès le premier tour avec 53,3 % ; réélu en 2012 au second tour avec 50,3 % ; démissionne en 2016 après son élection à la région, ce qui provoque une législative partielle.",""],["","À chacune de ses nominations au gouvernement, il laisse son siège à sa suppléante Pascale Gruny. Il retrouve son siège en février 2009, étant le premier à bénéficier de la loi permettant aux membres sortants d'un gouvernement de récupérer leur mandat sans élection partielle.",""],["","Assistant parlementaire de Jacques Braconnier, sénateur de l'Aisne, de 1987 à 1992 : fonction, pas un mandat.",""]]],["Au gouvernement",[["31/03/2004 - 31/05/2005","Secrétaire d'État chargé de l'Assurance maladie, gouvernement Raffarin III",""],["","Ministre de la Santé et des Solidarités, gouvernement Villepin, 02/06/2005 - 26/03/2007 (démissionne pour être porte-parole de la campagne de Nicolas Sarkozy)",""],["18/05/2007 - 18/03/2008","Ministre du Travail, des Relations sociales et de la Solidarité, gouvernements Fillon I et II",""],["18/03/2008 - 15/01/2009","Ministre du Travail, des Relations sociales, de la Famille et de la Solidarité, gouvernement Fillon II",""],["14/11/2010 - 10/05/2012","Ministre du Travail, de l'Emploi et de la Santé, gouvernement Fillon III",""]]],["Mandats locaux",[["","Conseiller municipal de Saint-Quentin (Aisne) depuis 1995, toujours en cours",""],["","Adjoint au maire de Saint-Quentin à partir de 1995 (redynamisation), reconduit en 2001 (animation et développement de la ville)",""],["","Conseiller général de l'Aisne, élu en 1998",""],["","Conseiller puis vice-président de la communauté d'agglomération de Saint-Quentin",""],["","Maire de Saint-Quentin, élu le 04/10/2010 ; quitte la mairie en 2016 comme la loi sur le non-cumul l'y oblige, tout en restant conseiller municipal",""],["","Président de la communauté d'agglomération de Saint-Quentin, puis du Saint-Quentinois, de 2014 à 2020 ; ne se représente pas en 2020",""],["","Président du conseil régional des Hauts-de-France depuis le 04/01/2016 (élu tête de liste en 2015 avec 57,8 % au second tour, face à Marine Le Pen), réélu le 27/06/2021 avec 52,4 %",""],["","Fonctions non électives : secrétaire général de l'UMP de 2009 à 2010, président de Nous France.",""]]]],"parcours":[["Profession",[["","Agent général d'assurance pour Swiss Life de 1992 à 2004. Maîtrise de droit public et DESS d'administration locale, université de Reims.",""]]],["Parti et responsabilités",[["","Président de Nous France, parti qu'il lance en octobre 2022",""],["","Secrétaire général de l'UMP, par intérim à partir de 2008 puis en titre de 2009 à 2010",""],["","Assistant parlementaire du sénateur Jacques Braconnier de 1987 à 1992",""],["","Porte-parole de la campagne de Nicolas Sarkozy en 2007",""]]]],"judiciaire":[["","Aucune condamnation documentée.",""],["","1. Mediapart a rapporté en mai 2020 qu'une enquête judiciaire portait sur des repas politiques financés sur fonds régionaux, pour plus de 7 000 euros. Une enquête n'est pas une condamnation, et son issue n'est pas connue.",""],["","2. Affaire du Mediator : il a été entendu comme témoin au procès en 2020, et auditionné en 2020 par la commission d'enquête de l'Assemblée sur le Covid en tant qu'ancien ministre de la Santé. Il n'est pas mis en cause judiciairement dans les sources ouvertes ici.",""]],"sources":"• Éléments transmis par la rédaction (déclaration du 27/08/2026, liens)\n• LCP - Assemblée nationale, liste des candidats, maj 06/09/2026\n• Wikipédia, « Xavier Bertrand », consulté le 08/09/2026","pva":false},{"id":"fabien-roussel","slug":"fabien-roussel","date":"06/09/2026","statut":"déclaré","site":"https://www.fabienroussel2027.fr","prog_url":"https://www.pcf.fr/le_programme","prog":"en cours","past":["➖","✅","➖","✅","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire. Battu au premier tour des législatives de 2024 avec 31,2 % des voix, face à Guillaume Florquin (RN, 50,3 %), qui fait basculer une circonscription détenue par le PCF depuis 1962.",""],["","Maire de Saint-Amand-les-Eaux (Nord) depuis le 30 janvier 2025.",""]]],["Mandats parlementaires passés",[["","Député de la 20e circonscription du Nord du 21 juin 2017 au 9 juin 2024, sans interruption :",""],["","Élu en 2017 avec 63,88 % au second tour, face au Front national, avec pour suppléant le député sortant Alain Bocquet, non candidat à sa succession",""],["","Réélu en 2022 avec 54,50 % au second tour, investi par le PCF dans le cadre de la NUPES",""],["","Battu au premier tour en 2024, mandat clos le 09/06/2024",""],["","Inscrit au groupe de la Gauche démocrate et républicaine (GDR). Membre de la commission des Finances. Rapporteur, en 2017-2018, d'une proposition de loi créant une liste française des paradis fiscaux.",""],["","À ne pas compter comme mandats : conseiller de cabinet de Michelle Demessine à partir de 1997, puis attaché ou assistant parlementaire d'Alain Bocquet, de Jean-Jacques Candelier (2009-2014) et de Michelle Demessine (2015-2017). Ce sont des emplois, pas des mandats - et c'est précisément l'objet de l'enquête mentionnée en colonne judiciaire.",""]]],["Au gouvernement",[["","Aucune. Il a été conseiller chargé de la communication au cabinet de Michelle Demessine, secrétaire d'État au Tourisme, à partir de 1997 : fonction de cabinet, pas une fonction gouvernementale.",""]]],["Mandats locaux",[["","Conseiller municipal de Saint-Amand-les-Eaux depuis mars 2014, élu sur la liste conduite par le député-maire sortant Alain Bocquet, d'abord chargé de la culture et des festivités",""],["","Conseiller communautaire de la Porte du Hainaut depuis mars 2014",""],["","Maire de Saint-Amand-les-Eaux depuis le 30 janvier 2025, à la suite de la démission d'Alain Bocquet",""],["","Candidatures non élues, à ne pas compter comme mandats : cantonales de 2004 dans le canton de Lille-Sud-Ouest (5,2 %, cinquième) ; tête de liste PCF aux régionales de 2015 en Nord-Pas-de-Calais-Picardie (5,3 %, liste non maintenue au second tour, aucun élu). Il n'a pas figuré sur les listes d'union de la gauche aux régionales de 2021.",""]]]],"parcours":[["Profession",[["","Journaliste. Stagiaire à L'Humanité en 1989, puis journaliste reporter d'images formé au CFPJ, pigiste pour France Télévisions entre 1995 et 1996, reportages au Viêt Nam et aux Kerguelen. Quitte le journalisme en 1997.",""]]],["Parti et responsabilités",[["","Secrétaire national du PCF depuis le 25/11/2018, réélu en avril 2023 avec 80,4 % des voix",""],["","Secrétaire de la fédération PCF du Nord depuis 2010",""],["","Conseiller chargé de la communication au cabinet de Michelle Demessine, secrétaire d'État au Tourisme, à partir de 1997",""],["","Attaché ou assistant parlementaire d'Alain Bocquet, de Jean-Jacques Candelier (2009-2014) et de Michelle Demessine (2015-2017). C'est l'objet de l'enquête mentionnée en colonne judiciaire.",""]]]],"judiciaire":[["","Aucune condamnation.",""],["","Une enquête préliminaire, sans issue connue à ce jour :",""],["","Le Parquet national financier a indiqué à la presse le 11 mars 2022 avoir ouvert une enquête préliminaire pour soupçons d'emploi fictif, après des révélations de Mediapart affirmant qu'il avait bénéficié, entre 2009 et 2014, d'un emploi d'attaché parlementaire de Jean-Jacques Candelier sans exercer réellement cette fonction.",""],["","Il conteste, affirme avoir travaillé avec ce député sur des conflits sociaux du Douaisis, et a mis en ligne des documents et témoignages pour sa défense. Jean-Jacques Candelier a maintenu publiquement qu'il était bien son assistant.",""]],"sources":"• Éléments transmis par la rédaction (déclaration du 06/09/2026, lien programme)\n• LCP - Assemblée nationale, liste des candidats, maj 06/09/2026\n• Wikipédia, « Fabien Roussel », consulté le 08/09/2026","pva":true},{"id":"tondelier","slug":"marine-tondelier","date":"22/10/2025","statut":"déclaré","site":"https://marinetondelier.fr","prog_url":"https://lesecologistes.fr/pages/6ImK65GKUnvibm33WGkjkj/projet-2027","prog":"publié","past":["➖","➖","➖","✅","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire, et elle n'en a jamais exercé.",""],["","Conseillère municipale d'opposition à Hénin-Beaumont depuis mars 2014 et conseillère régionale des Hauts-de-France depuis 2021, mandats en cours.",""]]],["Mandats parlementaires passés",[["","Aucun. Elle n'a jamais été députée, sénatrice ni députée européenne.",""],["","Candidatures non élues, à ne pas compter comme mandats : trois fois aux législatives dans la 11e circonscription du Pas-de-Calais, face à Marine Le Pen - 1,63 % au premier tour en 2012, 3,55 % en 2017, et 39 % au second tour en 2022 avec le soutien de la NUPES. Candidate en 74e position sur la liste EELV aux européennes de 2019.",""],["","À ne pas compter non plus : collaboratrice parlementaire de la sénatrice Aline Archimbaud de 2011 à 2015, puis de la députée Cécile Duflot de 2015 à 2017.",""]]],["Au gouvernement",[["","Aucune.",""],["","À ne pas confondre avec un mandat : déléguée générale de la Fédération Atmo France, fédération des associations agréées de surveillance de la qualité de l'air, de 2017 à 2022.",""]]],["Mandats locaux",[["","Conseillère municipale d'Hénin-Beaumont depuis mars 2014, dans l'opposition à la municipalité RN de Steeve Briois. Élue en 2014 en deuxième position d'une liste d'union PS-EELV-PRG-PCF (32,04 %), la liste FN l'emportant dès le premier tour avec 50,25 %. Réélue en 2020 comme tête de liste, avec 18,22 % contre 74,21 % au maire sortant.",""],["","Élue à la communauté d'agglomération Hénin-Carvin.",""],["","Élue le 23 septembre 2014 présidente du conseil de surveillance du centre hospitalier d'Hénin-Beaumont, face à Steeve Briois.",""],["","Conseillère régionale des Hauts-de-France depuis 2021, élue en deuxième position sur la liste d'union de la gauche dans le Pas-de-Calais (19,78 %).",""],["","Candidatures locales non élues : départementales de 2015 dans le canton d'Hénin-Beaumont-1 (6,50 %), tête de liste régionale dans le Pas-de-Calais en 2015 (4,83 %).",""]]]],"parcours":[["Profession",[["","Diplômée de l'IEP de Lille (2009) et titulaire d'un master en gestion des établissements de santé. Déléguée générale de la Fédération Atmo France, sur la qualité de l'air, de 2017 à 2022.",""]]],["Parti et responsabilités",[["","Secrétaire nationale d'EELV, devenu Les Écologistes, depuis le 10/12/2022, élue avec 90,8 % des voix des délégués",""],["","Membre du conseil fédéral d'EELV depuis 2011 et du bureau exécutif depuis 2013",""],["","Présidente du conseil de surveillance du centre hospitalier d'Hénin-Beaumont depuis septembre 2014 (fonction attachée à son mandat municipal)",""],["","Collaboratrice parlementaire de la sénatrice Aline Archimbaud (2011-2015) puis de la députée Cécile Duflot (2015-2017)",""],["","Directrice de campagne d'Éric Piolle à la primaire écologiste de 2021, puis porte-parole de Yannick Jadot pour la présidentielle de 2022",""]]]],"judiciaire":[["","Aucune condamnation. Une relaxe, à formuler précisément si elle est mentionnée :",""],["","Poursuivie en diffamation par Steeve Briois et Bruno Bilde à la suite de son livre « Nouvelles du Front » (2017), elle a été relaxée par le tribunal correctionnel de Paris. Le tribunal a estimé que les propos étaient bien diffamatoires, mais l'a relaxée, elle et son éditeur, au bénéfice de la bonne foi.",""],["","Formulation à respecter : « relaxée au bénéfice de la bonne foi », pas « blanchie » et pas « condamnée ». Elle était la partie poursuivie, à l'initiative de deux élus RN.",""]],"sources":"• Éléments transmis par la rédaction (déclaration du 22/10/2025, désignation du 08/12/2025, lien Projet 2027)\n• LCP - Assemblée nationale, liste des candidats, maj 06/09/2026\n• Wikipédia, « Marine Tondelier », consulté le 08/09/2026","pva":true},{"id":"francois-ruffin","slug":"francois-ruffin","date":"26/01/2026","statut":"déclaré","site":"https://nouspresident.fr","prog_url":"https://nouspresident.fr/cahiers-de-campagne/","prog":"en cours","past":["✅","✅","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Député de la première circonscription de la Somme depuis juin 2017, mandat en cours. Membre de la commission des Affaires économiques. Siège au groupe Écologiste et Social depuis juillet 2024.",""]]],["Mandats parlementaires passés",[["","Même circonscription depuis 2017, sans interruption, trois mandats :",""],["","Élu en juin 2017 sous la bannière « Picardie debout ! » avec 55,97 % au second tour, soutenu par LFI, le PCF, EELV et Ensemble !",""],["","Réélu en juin 2022 avec 61 % dans le cadre de la NUPES",""],["","Réélu de justesse en juillet 2024 avec 52,96 %, après le désistement au nom du front républicain de la candidate Renaissance arrivée troisième",""],["","PARCOURS DE GROUPE, à suivre de près : élu secrétaire de la commission des Affaires économiques en 2017. Siège au groupe La France insoumise de 2017 à 2024 sans jamais adhérer au mouvement ni signer sa charte. Rompt avec LFI pendant la campagne de 2024 et rejoint le groupe écologiste, sans adhérer à aucun parti.",""]]],["Au gouvernement",[["","Aucune.",""]]],["Mandats locaux",[["","Aucun mandat local relevé. Il n'a jamais exercé de mandat municipal, départemental ou régional : son seul mandat électif est celui de député.",""]]]],"parcours":[["Profession",[["","Journaliste, essayiste et documentariste. Diplômé du CFJ en 2002. Fondateur et rédacteur en chef du journal Fakir depuis 1999, reporter pour Là-bas si j'y suis de 2005 à 2012, réalisateur de quatre documentaires. Sa fiche de l'Assemblée nationale le déclare « reporter ».",""]]],["Parti et responsabilités",[["","Président du parti Debout !, lancé en juin 2025, après avoir créé le micro-parti Picardie debout ! en février 2019",""],["","Fondateur et rédacteur en chef du journal Fakir depuis 1999",""],["","Secrétaire de la commission des Affaires économiques de l'Assemblée nationale à partir de 2017",""]]]],"judiciaire":[["","Une condamnation ancienne :",""],["2008","Condamné pour diffamation par le tribunal d'Amiens, à la suite d'une plainte déposée par un habitant du quartier au sujet de son livre « Quartier Nord » (2006), enquête sur les quartiers nord d'Amiens. C'est une condamnation civile pour diffamation liée à son activité de journaliste, pas une affaire de probité publique : ne pas la mettre sur le même plan qu'un détournement de fonds.",""],["","Deux sanctions internes à l'Assemblée, disciplinaires et non judiciaires : retenue d'un quart d'indemnité pendant un mois en décembre 2017 pour port d'un maillot de football à la tribune, et rappels à l'ordre pour avoir fait la promotion de son journal Fakir.",""],["2023","La Haute Autorité pour la transparence de la vie publique a relevé une sous-évaluation de sa société de production dans sa déclaration de patrimoine. Suites de cette procédure inconnues.",""],["","À ne pas confondre : dans l'affaire d'espionnage par LVMH, il est la partie surveillée, pas la partie mise en cause. Bernard Squarcini, ancien patron du renseignement intérieur, a été condamné en 2025 notamment pour une opération de surveillance visant Ruffin et Fakir.",""]],"sources":"• Éléments transmis par la rédaction (déclaration du 26/01/2026, cahiers de campagne)\n• LCP - Assemblée nationale, liste des candidats, maj 06/09/2026\n• Wikipédia, « François Ruffin », consulté le 08/09/2026","pva":true},{"id":"karim-bouamrane","slug":"karim-bouamrane","date":"09/06/2026","statut":"déclaré","site":"https://www.karimbouamrane2027.org","prog_url":"https://www.karimbouamrane2027.org","prog":"en cours","past":["➖","➖","➖","✅","✅"],"mandats":[["Mandat parlementaire actuel",[["","Jamais exercé de mandat parlementaire",""]]],["Mandats parlementaires passés",[["","Jamais exercé de mandat parlementaire",""]]],["Au gouvernement",[["","Jamais de fonction gouvernementale",""]]],["Mandats locaux",[["","MANDATS LOCAUX ACTUELS :",""],["","Maire de Saint-Ouen-sur-Seine : réélu en mars 2026, c'est un mandat qu'il occupe depuis le 4 juillet 2020 (avec des mandats successifs)",""],["","Membre du conseil départemental de Seine-Saint-Denis",""],["","Vice-Président du Conseil départemental délégué à la culture",""],["","Conseiller territorial",""],["","MANDATS LOCAUX PASSÉS",""],["1995-2014","Conseiller municipal de Saint-Ouen-sur-Seine",""],["4 juillet 2020","Maire de Saint-Ouen-sur-Seine",""],["","Président du conseil de surveillance de la Société des grands projets (2022-2026)",""]]]],"parcours":[["Profession",[["","Karim Bouamrane obtient un master en économie et droit européen. Entre 2012 et 2015, il est vice-président chez Xirrus. Il rejoint ensuite Guidance Software comme directeur channel EMEA, puis Bitglass en 2018 comme directeur Europe du Sud",""]]],["Parti et responsabilités",[["","Conseiller métropolitain depuis septembre 2020, vice-président de septembre 2020 à juillet 2021 puis conseiller métropolitain.",""],["","Vice-président du conseil départemental depuis juillet 2021",""]]]],"judiciaire":[["","Soupçon d'emploi de complaisance en Seine-Saint-Denis. Le maire a poussé l'embauche d'une proche comme chargée de mission au département. Pour l'instant pas de condamnation.",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"delphine-batho","slug":"delphine-batho","date":"26/11/2025","statut":"déclaré","site":"https://www.delphinebatho.fr","prog_url":"https://www.generationecologie.fr","prog":"en cours","past":["✅","✅","✅","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Députée de la 2e circonscription des Deux-Sèvres, mandat en cours. Membre de la commission de la Défense nationale et des forces armées. Siège au groupe Écologiste et Social. Suppléant : Olivier Cubaud. Rattachement au titre du financement de la vie politique : Les Écologistes - EELV.",""]]],["Mandats parlementaires passés",[["","Même circonscription depuis 2007, cinq mandats, environ dix-huit ans à l'Assemblée :",""],["2007-2012","Élue en juin 2007 avec 57,42 % au second tour, succédant à Ségolène Royal qui ne se représentait pas. Vice-présidente du groupe socialiste, chargée de la sécurité.",""],["2012-2017","Réélue dès le premier tour avec 53,18 %. Nommée au gouvernement, elle laisse son siège ; elle reprend l'exercice de son mandat le 03/08/2013 comme ancien membre du gouvernement, jusqu'au 20/06/2017.",""],["2017-2022","Réélue le 18/06/2017 avec 56,94 %. Mandat du 21/06/2017 au 21/06/2022.",""],["2022-2024","Mandat du 22/06/2022 au 09/06/2024.",""],["","Depuis juillet 2024 : mandat en cours.",""],["","PARCOURS DE GROUPE, exceptionnellement mouvant : groupe socialiste (2007-2012) ; groupe Nouvelle gauche dont elle est vice-présidente (2017-2018) ; non-inscrite après son départ du PS en mai 2018 ; groupe Écologie démocratie solidarité dont elle est vice-présidente (mai 2020, dissous en octobre 2020) ; non-inscrite ; groupe Écologiste - NUPES (2022-2024), qu'elle quitte en octobre 2023 ; groupe Écologiste et Social depuis 2024.",""]]],["Au gouvernement",[["","Ministre déléguée à la Justice, gouvernement Ayrault I, nommée le 16 mai 2012, auprès de la garde des Sceaux Christiane Taubira",""],["","Ministre de l'Écologie, du Développement durable et de l'Énergie, gouvernement Ayrault II, de juin 2012 au 2 juillet 2013",""],["","Fin de fonctions le 2 juillet 2013 : le président de la République met fin à ses fonctions après une interview où elle qualifie de « mauvais » le budget 2014 de son ministère. Elle déclare n'avoir commis « ni une erreur ni une faute » et met en cause des lobbys économiques.",""]]],["Mandats locaux",[["","Aucun mandat local relevé. Son seul mandat électif est celui de députée.",""],["","À ne pas compter comme mandats : collaboratrice de Julien Dray au conseil régional d'Île-de-France sur les questions de sécurité (à partir de 2003), présidence de la FIDL, vice-présidence de SOS Racisme (1992-1998), secrétaire nationale du PS chargée de la sécurité, présidence de Génération écologie depuis septembre 2018. Candidate en position non éligible aux européennes de 2019 sur la liste « Urgence écologie » (1,82 %).",""]]]],"parcours":[["Profession",[["","Cadre territorial, selon sa fiche de l'Assemblée nationale. Études d'histoire à Paris 7, non achevées. Auditrice de l'INHESJ en 2006.",""]]],["Parti et responsabilités",[["","Présidente de Génération écologie depuis septembre 2018, succédant à Yves Piétrasanta",""],["","Vice-présidente du groupe socialiste à l'Assemblée nationale, chargée de la sécurité, de 2007 à 2012 ; vice-présidente du groupe Nouvelle gauche de 2017 à 2018 ; vice-présidente du groupe Écologie démocratie solidarité en 2020",""],["","Secrétaire nationale du PS chargée de la sécurité à partir de 2006, membre du bureau national depuis 2000",""],["","Présidente de la FIDL à partir de 1990, vice-présidente de SOS Racisme de 1992 à 1998",""],["","Collaboratrice de Julien Dray au conseil régional d'Île-de-France sur les questions de sécurité, à partir de 2003",""],["","Porte-parole de François Hollande pour la présidentielle de 2012, puis de Yannick Jadot en décembre 2021",""]]]],"judiciaire":[["","Aucune condamnation.",""],["","À ne pas confondre : en janvier 2018 elle a attaqué le Parti socialiste en justice sur les modalités d'organisation de son congrès. Elle était la partie demanderesse, et elle a été déboutée.",""],["","Polémique non judiciaire, à ne mentionner que si elle sert le propos : en 2012, avant sa nomination au gouvernement, elle a quitté un logement du parc social parisien qu'elle occupait depuis 2001, après plusieurs mois de demandes du bailleur.",""]],"sources":"• Éléments transmis par la rédaction (déclaration du 26/11/2025, piliers de Génération écologie)\n• Fiche de la députée sur assemblee-nationale.fr, consultée le 08/09/2026 (source primaire : mandat en cours, groupe, commission, rattachement financier)\n• LCP - Assemblée nationale, liste des candidats, maj 06/09/2026\n• Wikipédia, « Delphine Batho », consulté le 08/09/2026","pva":true},{"id":"nathalie-arthaud","slug":"nathalie-arthaud","date":"08/12/2025","statut":"déclaré","site":"https://www.lutte-ouvriere.org","prog_url":"https://www.lutte-ouvriere.org/medias/document/fichiers/2026/06/brochure-ete-2026.pdf","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Pas de mandat",""]]],["Mandats parlementaires passés",[["","Jamais été élue députée, sénatrice ou députée européenne",""]]],["Au gouvernement",[["","Jamais été ministre, secrétaire d'État ou membre d'un gouvernement. En tant que porte-parole et figure du mouvement révolutionnaire et trotskiste (Lutte ouvrière), son parti refuse toute participation à des gouvernements sous le système capitaliste",""]]],["Mandats locaux",[["","Conseillère municipale chargée de la Jeunesse de Vaulx-en-Velin (Rhône) entre 2008 et 2014",""]]]],"parcours":[["Profession",[["","Professeure d'économie-gestion en lycée professionnel actuellement à Aubervilliers",""]]],["Parti et responsabilités",[["","Porte-parole nationale de Lutte ouvrière depuis 2008",""]]]],"judiciaire":[["","Pas d'éléments déclarés",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"anasse-kazib","slug":"anasse-kazib","date":"01/06/2026","statut":"déclaré","site":"https://anasse2027.fr","prog_url":"https://anasse2027.fr/programme","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire",""]]],["Mandats parlementaires passés",[["","N'a jamais eu de mandat parlementaire",""]]],["Au gouvernement",[["","N'a jamais exercé d'activité gouvernementale",""]]],["Mandats locaux",[["","Aucun mandat",""]]]],"parcours":[["Profession",[["","A travaillé pour Sud Rail à la Gare du Bourget puis intègre Les Grandes Gueules de RMC (2018)",""]]],["Parti et responsabilités",[["","Délégué syndical de SUD Rail à la Gare du Bourget, il devient une figure du mouvement cheminot en 2018 + Depuis 2017, il est membre de Révolution permanente, courant du Nouveau Parti anticapitaliste qui prend son indépendance en 2021.",""]]]],"judiciaire":[["","Pas de condamnation, mais à la suite du 7 octobre 2023 et de la publication sur ses réseaux sociaux de messages de soutien au peuple palestinien, le parquet de Paris a engagé des poursuites à son encontre. Il a été convoqué devant le tribunal correctionnel de Paris, son procès devait se tenir en juin 2026 mais le procès a été renvoyé, le tribunal a transmis une QPC à propos de la loi sur l'apologie du terrorisme à la Cour de cassation.","https://www.lemonde.fr/societe/article/2026/06/26/le-proces-du-militant-trotskiste-anasse-kazib-pour-apologie-du-terrorisme-est-renvoye-apres-la-remise-en-cause-d-une-des-parties-civiles_6715808_3224.html"],["",")",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"selma-labib","slug":"selma-labib","date":"17/06/2026","statut":"déclaré","site":"Pas de site de campagne à ce jour","prog_url":"https://npa-revolutionnaires.org/campagnes-presidentielles","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun : Absence à l'annuaire officiel des parlementaires français",""]]],["Mandats parlementaires passés",[["","AUCUN : Absence à l'annuaire officiel des parlementaires français",""]]],["Au gouvernement",[["","AUCUN : Absence à l'annuaire officiel des parlementaires français",""]]],["Mandats locaux",[["","AUCUN : Absence à l'annuaire officiel des parlementaires français",""]]]],"parcours":[["Profession",[["","Conductrice de bus en Île-de-France.",""]]],["Parti et responsabilités",[["","Porte-parole et militante du parti d'extrême gauche NPA-Révolutionnaires (scission du NPA).",""]]]],"judiciaire":[["","Aucune",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"lydie-massard","slug":"lydie-massard","date":"02/04/2026","statut":"déclaré","site":"https://www.udb.bzh","prog_url":"https://www.udb.bzh","prog":"en cours","past":["➖","✅","➖","✅","✅"],"mandats":[["Mandat parlementaire actuel",[["","Aucun",""]]],["Mandats parlementaires passés",[["2019","Devient député européenne en septembre 2023",""],["2017","Deputé de la 3ème circonstription du Morbihan en tant que suppléante d'Anne Soreil",""],["2022","Député de la 3ème circonscription du Morbihan en tant que titulaire",""]]],["Au gouvernement",[["","Aucune",""]]],["Mandats locaux",[["","En 2021, elle est élue au Canton de Pontivy",""],["","En 2026, elle est élue conseillère municipale de Pontivy sur la liste conduite par Jean-Jacques Merceur",""]]]],"parcours":[["Profession",[["","À l'origine : bibliothécaire",""]]],["Parti et responsabilités",[["","Entre 2019 et 2023 elle est porte-parole de l'UDB puis à nouveau à partir de 2025",""],["","Candidate à la primaire de la gauche pour l'élection présidentielle de 2027",""]]]],"judiciaire":[["","Aucune condamnation",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"antoine-mikolajczak","slug":"antoine-mikolajczak","date":"27/06/2026","statut":"déclaré","site":"https://parti-equinoxe.fr/presidentielle-2027/","prog_url":"https://parti-equinoxe.fr/presidentielle-2027/","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Pas de mandat",""]]],["Mandats parlementaires passés",[["","Pas d'ancien mandat",""]]],["Au gouvernement",[["","Pas exercé de fonction parlementaire jusqu'alors",""]]],["Mandats locaux",[["","Pas de mandat local, ni actuel ni par le passé",""]]]],"parcours":[["Profession",[["","Ingénieur engagé dans des projets locaux d'énergies renouvelables",""]]],["Parti et responsabilités",[["","Candidat à l'élection présidentielle de 2027 pour Equinoxe suite à l'élection au jugement majoritaire des adhérents du parti",""]]]],"judiciaire":[["","Pas jusqu'à maintenant",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"clara-egger","slug":"clara-egger","date":"19/04/2026","statut":"déclaré","site":"https://solutiondemocratique.fr","prog_url":"https://solutiondemocratique.fr/parrainage2027/","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Elle n'en a aucun",""]]],["Mandats parlementaires passés",[["","Elle n'en a jamais eu",""]]],["Au gouvernement",[["","Elle n'en a pas",""]]],["Mandats locaux",[["","Elle n'en a jamais détenu",""]]]],"parcours":[["Profession",[["","À l'origine, elle est enseignante-chercheuse et politologue de profession",""]]],["Parti et responsabilités",[["","Candidature citoyenne à l'élection présidentielle de 2022 portée par le collectif Espoir RIC",""],["","Elle est la fondatrice et présidente du parti Solution Démocratique axé sur la démocratie directe et l'instauration du Référendum d'Initiative Citoyenne",""]]]],"judiciaire":[["","Aucune affaire judiciaire ni condamnation n'est recensée concernant Clara Egger",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"manolo-mlekuz","slug":"manolo-mlekuz","date":"Début 2026 (date à préciser)","statut":"déclaré","site":"https://trajectoire2027.fr","prog_url":"https://trajectoire2027.fr/programme.html","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Pas de mandat parlementaire actuel",""]]],["Mandats parlementaires passés",[["","Mandat parlementaire passés",""]]],["Au gouvernement",[["","Sans fonctions gouvernementales",""]]],["Mandats locaux",[["","Ne détient et n'a jamais détenu aucun mandat local",""]]]],"parcours":[["Profession",[["","N'a pas exercé de profession, il était étudiant en histoire avant de mettre ses études entre parenthèses pour se consacrer à son engagement politique et sa recherche de parrainages",""]]],["Parti et responsabilités",[["","Ses responsabilités sont d'ordre associatif et politique comme le fait qu'il soit fondateur et président du mouvement trajectoire",""]]]],"judiciaire":[["","Aucune affaire judiciaire ni d'aucune condamnation",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"florian-philippot","slug":"florian-philippot","date":"09/05/2026","statut":"déclaré","site":"https://les-patriotes.fr","prog_url":"https://les-patriotes.fr/projetpourlafrance/","prog":"en cours","past":["➖","✅","➖","✅","✅"],"mandats":[["Mandat parlementaire actuel",[["","Mandat parlementaire actuel",""]]],["Mandats parlementaires passés",[["","Mandat parlementaire passés -Député européen de juillet 2014 à juillet 2019 élu dans la circonscription de l'Est; non réélu en 2019",""]]],["Au gouvernement",[["","Aucune fonction ministérielle ou gouvernementale exercée",""]]],["Mandats locaux",[["","Conseiller municipal de Forbach élu en 2014",""],["","Conseiller régional du Grand Est, élu en 2015, il perd ce mandat en 2021",""],["","Conseiller régional aux élections de 2015 en Alsace-Champagne-Ardenne et Lorraine (devenue région Grand Est) jusqu'en 2021",""]]]],"parcours":[["Profession",[["","Inspecteur de l'administration",""]]],["Parti et responsabilités",[["","En 2017 il quitte le RN pour créer son propre parti : Les Patriotes",""]]]],"judiciaire":[["","En juillet 2020, il a été entendu dans l'information judiciaire concernant les emplois présumés fictifs d'assistants d'eurodéputés du FN/RN et placé sous le statut de témoin",""],["","En mai 2019, le parquet de Sarreguemines a ouvert une enquête après qu'il a décroché un drapeau européen du bâtiment des Finances publiques de Forbach",""],["","Philippot est visé par une plainte pénale du Qatar pour diffamation après des propos tenus lors d'une émission de radio du 9 janvier 2015 et une émission télévisée du 19 janvier 2015, il avait suggéré que le Qatar finançait le terrorisme ; le Qatar avait demandé qu'on lève l'immunité mais le 28 janvier 2016, la commission des affaires juridiques du Parlement européen recommande à l'unanimité de ne pas lever son immunité. Le 2 février 2016, le Parlement européen vote et confirme le refus de lever son immunité",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"francois-asselineau","slug":"francois-asselineau","date":"Mars 2026 (date à préciser)","statut":"déclaré","site":"https://upr.fr","prog_url":"https://upr.fr/notre-programme","prog":"en cours","past":["➖","➖","➖","➖","✅"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire actuellement",""]]],["Mandats parlementaires passés",[["","Aucun mandat parlementaire",""]]],["Au gouvernement",[["","Aucune fonctions gouvernementales",""]]],["Mandats locaux",[["","Conseiller de Paris, 19e arrondissement, du 25 mars 2001 au 24 mars 2008. Non réélu.",""],["","Aucun mandat local en cours.",""]]]],"parcours":[["Profession",[["","Inspecteur général des Finances",""]]],["Parti et responsabilités",[["","Président de l'Union populaire républicaine qu'il a fondée lui-même le 25 mars 2007 et qu'il préside depuis",""],["","Il siège brièvement au groupe UMP au Conseil de Paris avant de rejoindre les non-inscrits en 2006 suite à des divergences sur la ligne européenne et les relations avec les US",""]]]],"judiciaire":[["","Aucune condamnation pénale définitive n'est établie mais une procédure judiciaire est en cours.",""],["","En mars 2020, une première enquête est ouverte après la plainte d'un collaborateur du parti UPR qui affirme avoir subi du harcèlement dès son arrivée et arrivés d'avoir forcé à accepter des baisers, un second collaborateur dénonce des faits similaires dans une plainte déposée en juin 2020. En février 2021 Asselineau est placé en garde à vue et confronté aux deux plaignants qui maintiennent leur version des faits. Lui nie toute agression sexuelle. En 2021 il a été mis en examen dans cette affaire puis de nouveau mis en examen pour \"harcèlement moral\", \"harcèlement sexuel\", \"agression sexuelle\".",""],["","Le 6 décembre 2024, les juges d'instruction rendent une ordonnance de non-lieu, le parquet de Paris fait immédiatement appel de cette décision. 7 avril 2026, la cour d'appel de Paris infirme le non-lieu et ordonne le renvoi de François Asselineau devant le tribunal correctionnel de Paris.",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"nicolas-dupont-aignan","slug":"nicolas-dupont-aignan","date":"08/03/2025","statut":"déclaré","site":"https://www.debout-la-france.fr","prog_url":"https://www.debout-la-france.fr/notre-projet/","prog":"en cours","past":["➖","✅","➖","✅","✅"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire depuis juin 2024 : battu aux législatives par Bérenger Cernon, après vingt-sept ans à l'Assemblée.",""],["","Maire d'Yerres (Essonne) depuis mars 2026, mandat en cours.",""]]],["Mandats parlementaires passés",[["","Député de la 8e circonscription de l'Essonne de 1997 à 2024, sans interruption, six mandats :",""],["","Élu le 01/06/1997, mandat du 01/06/1997 au 18/06/2002",""],["","Réélu le 09/06/2002, mandat du 19/06/2002 au 19/06/2007",""],["","Réélu le 10/06/2007, mandat à partir du 20/06/2007",""],["","Réélu en 2012 avec 61,39 % au second tour",""],["","Réélu en 2017",""],["","Réélu en 2022 avec 58 % dans la circonscription ; mandat clos le 09/06/2024 après sa défaite",""],["","GROUPE : sa fiche officielle de la 13e législature le donne « député n'appartenant à aucun groupe », et NosDéputés le donne non-inscrit pour la législature 2022-2024. Debout la France n'a jamais eu de groupe parlementaire. Rattachement financier : Debout la France.",""],["","Commission de la défense nationale et des forces armées sous la 13e législature.",""]]],["Au gouvernement",[["","Aucune.",""],["","À ne pas compter comme fonction gouvernementale : sous-préfet en début de carrière, puis passage en cabinets ministériels. En 2017, il a été présenté par Marine Le Pen comme son futur Premier ministre en cas de victoire, dans le cadre d'un accord de gouvernement : une annonce de campagne, pas une fonction exercée.",""]]],["Mandats locaux",[["","Maire d'Yerres (Essonne) du 25/06/1995 au 18/03/2001, puis du 19/03/2001 au 16/03/2008, puis jusqu'en 2017. Il quitte la mairie en 2017 du fait de la loi sur le non-cumul des mandats, et laisse la place à son premier adjoint Olivier Clodong.",""],["","Président de la communauté d'agglomération du Val-d'Yerres du 21/06/2002 au 16/03/2008",""],["","Conseiller municipal d'Yerres depuis mars 2026, et à nouveau maire depuis mars 2026, élu avec 79,84 % des voix, avec le soutien du maire sortant qui redevient premier adjoint",""],["","Il revendique avoir été réélu trois fois au premier tour avec plus de 75 % des voix, dont 79,70 % en 2008.",""]]]],"parcours":[["Profession",[["","Administrateur civil, selon sa fiche de l'Assemblée nationale. Énarque, diplômé de Sciences Po. Débute comme sous-préfet, puis passage en cabinets ministériels.",""]]],["Parti et responsabilités",[["depuis le 23/11/2008","Président de Debout la République, devenu Debout la France",""]]]],"judiciaire":[["","Non documenté à ce stade. À traiter, s'il y a lieu, uniquement sur décisions de justice comme sources primaires.",""]],"sources":"• Éléments transmis par la rédaction (déclaration du 08/03/2025, lien programme)\n• Fiche du député, XIIIe législature, assemblee-nationale.fr, consultée le 08/09/2026 (source primaire : dates de mandat 1997-2007, absence de groupe, mandats locaux)\n• Wikipédia, « Marine Le Pen », consulté le 08/09/2026, pour le ralliement de 2017 et son score de 4,70 %\n• LCP - Assemblée nationale, liste des candidats, maj 06/09/2026\n• Wikipédia, « Nicolas Dupont-Aignan », et NosDéputés.fr : consultés en recherche, à ouvrir et recouper avant passage en « sourcé »","pva":true},{"id":"juan-branco","slug":"juan-branco","date":"19/12/2025","statut":"déclaré","site":"https://ruches.org","prog_url":"https://ruches.org/le-projet","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun",""]]],["Mandats parlementaires passés",[["","Aucun",""]]],["Au gouvernement",[["","Aucune",""]]],["Mandats locaux",[["","Aucun",""]]]],"parcours":[["Profession",[["","Avocat, écrivain et docteur en droit.  Son cabinet intervient principalement en droit pénal, en droit international et dans la défense des libertés fondamentales",""]]],["Parti et responsabilités",[["","Avocat, inscrit au barreau de Paris depuis 2017 (avant sa radiation prononcée en 2025).",""],["","A travaillé pour WikiLeaks, comme salarié/collaborateur, de 2015 à 2019, et a défendu Julian Assange.",""],["","A rejoint l'équipe de défense de l'opposant sénégalais Ousmane Sonko au printemps 2023.",""],["","Représentant légal de victimes palestiniennes devant la Cour pénale internationale, mentionné dans une décision du 23 août 2024 relative à la situation en Palestine.",""],["","Auteur de plusieurs essais (Crépuscule, Assange l'antisouverain, Abattre l'ennemi, Treize pillards, Coup d'État, Paroles, Comment fabriquer une guillotine).",""],["","Engagement militant au sein du mouvement des Gilets jaunes depuis 2018.",""]]]],"judiciaire":[["","Mis en examen pour viol dans une information judiciaire ouverte en 2021 au pôle instruction du tribunal de Paris (affaire le mettant en cause suite à la plainte d'une actrice, désignée comme « Nissia B. » dans la presse). Aucune condamnation pénale n'est mentionnée dans les sources consultées à ce stade, le statut de mis en examen ne constitue pas une condamnation.",""],["","En parallèle, une procédure disciplinaire a été ouverte par l'Ordre des avocats de Paris en juin 2023 pour avoir publié, sur X et sur son site, des extraits de cette procédure judiciaire couverts par le secret de l'instruction.",""],["Août 2023","Sanctionné par le barreau de Paris à une interdiction d'exercer de neuf mois pour violation du secret de l'instruction. Il fait appel de cette décision.",""],["","Une demande de radiation est ensuite portée par le premier président de la cour d'appel de Paris, le président du tribunal judiciaire et le parquet général.",""],["","Le conseil de discipline du barreau de Paris devait statuer sur ce risque de radiation lors d'une audience fixée au 25 juin (année non précisée clairement dans les sources, probablement 2024 ou 2025 selon les articles).",""],["","Au Sénégal : inculpé et écroué le 6 août 2023 à Dakar pour des faits liés à « attentat », « complot », « diffusion de » (la source est tronquée sur ce point) - dans le contexte de sa défense de l'opposant Ousmane Sonko ; il est ensuite libéré sous contrôle judiciaire le 7 août 2023, puis fait l'objet d'un mandat d'arrêt international sénégalais annoncé courant 2023, après la publication de plaintes contre le président Macky Sall pour crimes contre l'humanité.",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"francis-lalanne","slug":"francis-lalanne","date":"19/08/2026","statut":"déclaré","site":"https://dieudolalanne2027.com","prog_url":"https://dieudolalanne2027.com/programme/","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun.",""]]],["Mandats parlementaires passés",[["","Aucun. Il s'est présenté sans succès à plusieurs élections :",""],["","Législatives de 2007, 2e circonscription du Nord, pour le Mouvement écologiste indépendant",""],["","Législatives de 2017, 10e circonscription des Hauts-de-Seine",""],["","Européennes de 2019, coconducteur de la liste « Alliance jaune »",""],["","Européennes de 2024, sur la liste « France libre » menée par Dieudonné",""]]],["Au gouvernement",[["","Aucune.",""]]],["Mandats locaux",[["","Aucun.",""]]]],"parcours":[["Profession",[["","Auteur-compositeur-interprète, comédien, écrivain et poète.",""]]],["Parti et responsabilités",[["","Candidat du Parti France Libre à l'élection présidentielle de 2027",""],["","Coconducteur de la liste « Alliance jaune » aux européennes de 2019",""],["","Ancien président de l'association « Un million d'arbres »",""]]]],"judiciaire":[["","Le Conseil constitutionnel l'a déclaré inéligible pour dix-huit mois en avril 2025, pour défaut de dépôt de ses comptes de campagne aux législatives de 2024. ⚠️ Cette peine est arrivée à échéance : il est éligible pour 2027.",""],["","Autres décisions :",""],["Février 2023","800 euros d'amende pour harcèlement moral envers son ex-conjointe, avec interdiction de se présenter à son domicile.",""],["6 mars 2025","Déclaré coupable de vol et de dégradation envers son ex-compagne par le tribunal correctionnel d'Aix-en-Provence.",""],["2 octobre 2025","Jugé pour abandon de famille, pour n'avoir pas versé de pension alimentaire. ⚠️ Issue inconnue.",""]],"sources":"Éléments transmis par la rédaction (dates de déclaration, liens) · Site de campagne dieudolalanne2027.com.","pva":false},{"id":"benoit-mathieu","slug":"benoit-mathieu","date":"30/03/2026","statut":"déclaré","site":"https://benoit.mathieu.wiki/index.php/Accueil","prog_url":"https://benoit.mathieu.wiki/index.php/Programme","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun",""]]],["Mandats parlementaires passés",[["","Aucun",""]]],["Au gouvernement",[["","Aucun",""]]],["Mandats locaux",[["","Aucun",""]]]],"parcours":[["Profession",[["","Ingénieur de formation et ancien professeur contractuel de mathématiques",""]]],["Parti et responsabilités",[["","Acteur de la société civile, c'est-à-dire qu'il n'occupe pas de fonction publique nommée ou d'appareil politique, il s'investit principalement dans sa démarche citoyenne de terrain",""]]]],"judiciaire":[["","Aucune condamnation ni mise en examen connue",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)","pva":false},{"id":"glucksmann","slug":"raphael-glucksmann","date":"23/08/2026","statut":"déclaré","site":"https://glucks2027.fr","prog_url":"https://place-publique.eu/pages/69jA2SKIG5udlNX7wI3dmc/le-projet","prog":"en cours","past":["✅","✅","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Député européen, réélu en juin 2024 (2024-2029), il siège au sein du groupe de l'Alliance Progressiste des Socialistes et Démocrates",""]]],["Mandats parlementaires passés",[["","Député européen entre 2019 et 2024, notamment président de la Commission spéciale sur l'ingérence étrangère dans l'ensemble des processus démocratiques de l'UE",""]]],["Au gouvernement",[["","Aucune",""]]],["Mandats locaux",[["","Aucune",""]]]],"parcours":[["Profession",[["","Essayiste et journaliste",""]]],["Parti et responsabilités",[["","Cofondateur du mouvement politique Place publique depuis 2018",""],["","Conseiller auprès du président géorgien Mikheil Saakachvili entre 2009 et 2012 sur les questions d'intégration européenne",""],["","Directeur de la rédaction du magazine Le Nouveau Magazine littéraire entre 2017-2018",""]]]],"judiciaire":[["","Aucune condamnation, ni mise en examen connue à ce jour",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)                                                               *https://www.europarl.europa.eu/meps/fr/197694/RAPHAEL_GLUCKSMANN/main-activities/plenary-speeches                                                                              https://howtheyvote.eu/votes?q=GLUCKSMANN","pva":true},{"id":"bernard-cazeneuve","slug":"bernard-cazeneuve","date":"16/07/2026","statut":"déclaré","site":"https://www.la-convention.fr","prog_url":"https://www.la-convention.fr","prog":"en cours","past":["➖","✅","✅","➖","✅"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat actuel",""]]],["Mandats parlementaires passés",[["","14ème législature : mandat du 16 juin 2017 au 20 juin 2017 (fin de législature)",""],["","14ème législature : mandat du 20 juin 2012 au 21 juillet 2012 (nomination comme membre du Gouvernement)",""],["","13ème législature : mandat du 20 juin 2007 au 16 juin 2012 (nomination comme membre du gouvernement)",""],["","11ème législature : mandat du 1er juin 1997 au 18 juin 2002",""]]],["Au gouvernement",[["","Ministre délégué chargé des Affaires européennes auprès du Ministre des Affaires étrangères, nommé en mai 2012",""],["","Ministre délégué chargé du Budget à partir de mars 2013 suite à la démission de Cahuzac",""],["","Ministre de l'Intérieur nommé le 1er avril 2014 à décembre 2016",""],["","Premier ministre du 6 décembre 2016 au 10 mai 2017",""]]],["Mandats locaux",[["","Aucun actuels",""],["","Passés :",""],["1994","Conseiller général d'Octeville",""],["1995-2000","Maire d'Octeville",""],["2001-2012","Maire de Cherbourg-Octeville",""],["2008-2012","Président de la Communauté urbaine de Cherbourg",""],["2004-2007","Premier vice-président de la Région Basse-Normandie",""]]]],"parcours":[["Profession",[["","Avocat",""]]],["Parti et responsabilités",[["1997-2002","Juge titulaire de la Haute Cour de justice et de la Cour de justice de la République",""],["","Depuis 2017 : avocat associé au cabinet August Debouzy",""],["","Lancé le 1er février 2023 : fondateur et figure tutélaire du mouvement politique \"La Convention\"",""],["","Publication d'une \"Lettre au Français\" le 17 juillet 2026",""]]]],"judiciaire":[["","En 2023, un policier a déposé plainte contre Bernard Cazeneuve devant la Cour de Justice de la République pour \"homicide involontaire\" en sa qualité de ministre de l'Intérieur le soir de l'attentat de Nice le 14 juillet 2016",""]],"sources":"• Éléments transmis par la rédaction (dates de déclaration, liens)https://www.assemblee-nationale.fr/14/pdf/cr-cloi/14-15/c1415058.pdf \nhttps://www.assemblee-nationale.fr/14/pdf/cr-cloi/13-14/c1314075.pdf \nhttps://www.assemblee-nationale.fr/14/pdf/cr-cloi/15-16/c1516050.pdf                  https://www.assemblee-nationale.fr/14/pdf/cr-cloi/15-16/c1516057.pdf                    https://www.franceinfo.fr/faits-divers/justice-proces/attentat-de-nice-en-2016-l-ancien-ministre-de-l-interieur-bernard-cazeneuve-vise-par-une-plainte-pour-homicide-involontaire_6211503.html","pva":false},{"id":"eric-zemmour","slug":"eric-zemmour","date":"17/09/2026","statut":"déclaré","site":"https://www.parti-reconquete.fr","prog_url":"https://leprogrammepourlafrance.fr","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat électif, actuel ou passé.",""]]],["Mandats parlementaires passés",[["","Aucun.",""]]],["Au gouvernement",[["","Aucune : il n'a jamais été ministre.",""]]],["Mandats locaux",[["","Aucun.",""]]]],"parcours":[["Profession",[["","Journaliste et essayiste. Né le 31 août 1958.",""]]],["Parti et responsabilités",[["","Président de Reconquête depuis le 5 décembre 2021, parti qu'il a fondé",""],["","Éditorialiste et chroniqueur, en presse écrite et audiovisuelle",""]]]],"judiciaire":[["","⚠️ Douze condamnations, dont neuf définitives. Aucune relaxe n'a tenu : les deux prononcées ont été cassées.",""],["","RACISME ET HAINE - six condamnations",""],["2011","Provocation à la discrimination raciale (propos de 2010 sur l'emploi et la délinquance). Définitive.",""],["2018","Provocation à la haine religieuse envers les musulmans. 5 000 €. ⚠️ Confirmée jusqu'à la CEDH, qui écarte son recours en 2022.",""],["2022","Complicité d'injure raciale et provocation à la haine (mineurs isolés, CNews 2020). 10 000 €. Définitive. ⚠️ Le CSA a par ailleurs infligé 200 000 € à CNews pour ces propos - première sanction pécuniaire contre une chaîne d'info ; recours rejeté par la CEDH en 2025.",""],["2023","Injure raciste envers Hapsatou Sy. 4 000 € + 3 000 €. Définitive en 2025.",""],["2024","Incitation à la haine contre les migrants et les mineurs isolés, injures à raison de l'origine (convention de la droite, 2019). 15 000 €. Définitive en 2025, après une relaxe cassée.",""],["2025","Injure raciale (affaire de Crépol). 9 000 €. ⚠️ Suite de la procédure inconnue.",""],["","DIFFAMATION - trois condamnations, toutes définitives",""],["2024","Envers Patrick Klugman (affaire Jérémie Cohen). Définitive en 2025.",""],["2024","Complicité de diffamation envers la députée Danièle Obono. 1 000 € avec sursis + 1 000 €. Définitive en 2026.",""],["2024","Envers l'INED, avec CNews, pour l'avoir accusé de truquer ses chiffres sur l'immigration. Définitive en 2026.",""],["","CONTREFAÇON - deux condamnations",""],["2022","165 000 €, avec Reconquête, pour des extraits de films dans son clip d'annonce de candidature. Plaignants : Gaumont, EuropaCorp, Besson, Ozon, la SACD, les ayants droit de Verneuil et Prévert. Pas d'appel.",""],["2026","Extraits du documentaire « Le Collège d'à côté » détournés dans un sens opposé à celui du film. ⚠️ Montant et suite de la procédure inconnus.",""],["","NÉGATIONNISME - une condamnation, non définitive",""],["2 avril 2025","Contestation de crime contre l'humanité, pour avoir affirmé que Pétain avait sauvé les juifs français. 10 000 €. 🔴 Il s'est pourvu en cassation. Relaxé deux fois avant cassation en 2023.",""]],"sources":"Le Monde avec AFP, article du 18 septembre 2026 sur la confirmation de sa candidature · Public Sénat, article du 18 septembre 2026 sur la même annonce · Site de Reconquête, page « J'agis », consultée le 15 octobre 2026 (source du parti) · Toute l'Europe · Wikipédia, article « Éric Zemmour », section polémiques · Éléments transmis par la rédaction.","pva":true},{"id":"olivier-becht","slug":"olivier-becht","date":"24/09/2026","statut":"déclaré","site":"https://becht2027.fr","prog_url":"https://becht2027.fr","prog":"","past":["✅","✅","✅","➖","✅"],"mandats":[["Mandat parlementaire actuel",[["","Député français de la 5e circonscription du Haut-Rhin, depuis 2017, réélu en 2022 et en 2024.",""]]],["Mandats parlementaires passés",[["","Député de la 5e circonscription du Haut-Rhin depuis 2017, réélu en 2022 et en 2024.",""],["","En 2012, il s'était présenté comme suppléant dans la même circonscription, aux côtés de la députée sortante Arlette Grosskost.",""]]],["Au gouvernement",[["","Il est nommé ministre délégué chargé du Commerce extérieur, de l’Attractivité et des Français de l’étranger dans le gouvernement Borne le 4 juillet 2022.",""]]],["Mandats locaux",[["","Maire de Rixheim (Haut-Rhin) de 2008 à 2017,",""],["","Président délégué de Mulhouse Alsace Agglomération",""],["","Conseiller départemental du Haut-Rhin (élu en 2015) et vice-président du conseil départemental jusqu’à son élection comme député en 2017.",""]]]],"parcours":[["Profession",[["","Magistrat administratif, puis enseignant à l'université. Né le 28 avril 1976 à Strasbourg.",""],["","Diplômé de l'Institut d'études politiques de Strasbourg, puis de l'École nationale d'administration, promotion 2002 - la même que celle d'Emmanuel Macron. Premier conseiller au tribunal administratif de Nancy, et enseignant à l'université de Haute-Alsace.",""]]],["Parti et responsabilités",[["","Élu en 2017 au sein du groupe Les Constructifs, devenu groupe UDI et indépendants ; président délégué de ce groupe en 2018",""],["","Président du groupe Agir ensemble à l'Assemblée nationale, du 26 mai 2020 au 21 juin 2022",""],["","Ancien magistrat administratif, puis enseignant à l'université.",""]]]],"judiciaire":[],"sources":"Sud Radio, « Qui est Olivier Becht, cet ancien ministre qui se lance dans la course à la Présidentielle ? », 8 octobre 2026 · Le JDD, 24 septembre 2026 · Site de campagne becht2027.fr.","pva":true},{"id":"mira-markovic","slug":"mira-markovic","date":"02/10/2026","statut":"déclarée","site":"https://parti-animaliste.fr/mira-markovic-2027","prog_url":"https://parti-animaliste.fr/programme","prog":"en cours","past":["➖","➖","➖","➖","✅"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire identifié.",""]]],["Mandats parlementaires passés",[["","Aucun mandat parlementaire identifié.",""]]],["Au gouvernement",[["","Aucune fonction gouvernementale identifiée.",""]]],["Mandats locaux",[["2014 - 2020","Conseillère municipale du 18e arrondissement de Paris, puis conseillère de Paris",""],["","Aucun mandat local en cours.",""]]]],"parcours":[["Profession",[["","Psychologue. Elle a exercé plus de dix-sept ans avant de se consacrer à la cause animale. 48 ans.",""]]],["Parti et responsabilités",[["","Cofondatrice du Parti animaliste en 2016, aux côtés notamment d'Hélène Thouy",""],["","Membre du Bureau national du parti depuis sa création",""],["","Candidate à l'élection présidentielle, désignée le 2 octobre 2026",""],["","Engagée depuis vingt-cinq ans pour la protection des animaux.",""]]]],"judiciaire":[["","Aucune information identifiée à ce jour.",""]],"sources":"Communiqué du Parti animaliste, « Mira Markovic représentera le Parti animaliste à la présidentielle », 2 octobre 2026 (source du parti) · Site du Parti animaliste, page « Mira Markovic 2027 », mise à jour le 12 octobre 2026 · Le Monde avec AFP, 2 octobre 2026.","pva":false},{"id":"natacha-polony","slug":"natacha-polony","date":"14/10/2026","statut":"déclarée","site":"https://natachapolony2027.fr","prog_url":"https://natachapolony2027.fr/natacha-polony/ma-vision","prog":"en cours","past":["➖","➖","➖","➖","➖"],"mandats":[["Mandat parlementaire actuel",[["","Aucun mandat parlementaire identifié.",""]]],["Mandats parlementaires passés",[["","Aucun mandat parlementaire identifié.",""]]],["Au gouvernement",[["","Aucune fonction gouvernementale identifiée.",""]]],["Mandats locaux",[["","Aucun mandat local identifié.",""]]]],"parcours":[["Profession",[["","Journaliste et essayiste. Née le 15 avril 1975 à Paris, de parents médecins, grandie dans le Val-d'Oise. Agrégée de lettres modernes en 1999, diplômée de Sciences Po en 2002.",""],["","Professeure de lettres stagiaire au lycée Jacques-Feyder d'Épinay-sur-Seine en 1999-2000, puis démissionne de l'Éducation nationale. Enseigne la culture générale à l'Institut Léonard de Vinci de 2002 à 2011.",""],["","Journaliste à Marianne aux pages éducation d'octobre 2002 à juin 2009, puis au Figaro jusqu'en juillet 2011. Chroniqueuse à « On n'est pas couché » (France 2, 2011-2014) et au « Grand Journal » (Canal+, 2014-2015). Revue de presse matinale sur Europe 1 de 2012 à 2017. Anime « Polonium » sur Paris Première (2015-2017), puis « Polonews » sur BFM TV (2021-2022). Chroniqueuse à « C l'hebdo » sur France 5 depuis 2023.",""],["","Directrice de la rédaction de Marianne à partir de septembre 2018, nommée par Daniel Křetínský.",""],["","Fondatrice en 2025 de la revue L'Audace !, qu'elle dirige.",""],["","Autrice d'une dizaine d'essais, dont « La France corps et âme » (Plon, 2026).",""]]],["Parti et responsabilités",[["","Secrétaire nationale chargée des questions de société au Mouvement des citoyens (MDC) de Jean-Pierre Chevènement, à partir de juin 2001",""],["","Membre du bureau du Pôle républicain, chargée du droit des femmes",""],["","Fondatrice du Comité Orwell (2015), devenu Comité Les Orwelliens",""],["","Fondatrice d'Orwell TV (2017), devenue Polony TV, intégrée à Marianne en 2020",""],["","Directrice de la rédaction de Marianne, 2018 - fin 2024",""],["","Fondatrice de la revue L'Audace ! (2025)",""],["","Elle a lancé son propre mouvement début septembre 2026, qui revendique 60 000 sympathisants.",""]]]],"judiciaire":[["","⚠️ Relaxée par le tribunal judiciaire de Paris, pour des propos sur le génocide des Tutsis.",""],["","Lors d'un débat sur France Inter en mars 2018, elle emploie une formule que des associations - Ibuka et la Licra - jugent négationniste. Le CSA relève qu'elle n'a pas remis en cause l'existence du génocide, mais informe Radio France de l'émoi suscité.",""],["","Renvoyée en correctionnelle en décembre 2020 contre l'avis du parquet, jugée le 1er mars 2022, elle est relaxée le 20 mai 2022 par le tribunal judiciaire de Paris.",""],["","Elle a par ailleurs obtenu 390 580 euros d'indemnités d'Europe 1 aux prud'hommes, pour licenciement sans cause réelle et sérieuse.",""]],"sources":"La Croix avec AFP, 14 octobre 2026 · Site de campagne natachapolony2027.fr, page biographique, consultée le 15 octobre 2026 (source de la candidate) · Site npolony.fr · Wikipédia, article « Natacha Polony », consulté le 15 octobre 2026.","pva":false}];
